<?php
require_once 'auth.php'; require_role(['super_admin','data_entry']); require_once 'db.php';
$message='';$type='error';$subjects=[];$q=mysqli_query($conn,'SELECT * FROM subjects WHERE is_active=1 OR EXISTS(SELECT 1 FROM results WHERE results.subject_id=subjects.id) ORDER BY year,semester,section,subject_code');while($x=mysqli_fetch_assoc($q))$subjects[]=$x;
if($_SERVER['REQUEST_METHOD']==='POST'){
 try {
  if(!verify_csrf())throw new DomainException('Invalid request.');
  $subjectId=(int)($_POST['subject_id']??0);$st=mysqli_prepare($conn,'SELECT subject_code FROM subjects WHERE id=?');mysqli_stmt_bind_param($st,'i',$subjectId);mysqli_stmt_execute($st);$sub=mysqli_fetch_assoc(mysqli_stmt_get_result($st));
  if(!$sub)throw new DomainException('Please select a valid subject.');
  create_result_record($conn,['student_id'=>strtoupper(trim($_POST['student_id']??'')),'year'=>(string)($_POST['year']??''),'semester'=>(string)($_POST['semester']??''),'subject_id'=>$subjectId,'subject_code'=>$sub['subject_code'],'marks'=>$_POST['marks']??'','entry_kind'=>$_POST['entry_kind']??'original','exam_date'=>trim($_POST['exam_date']??'')]);
  $message='Result added successfully. Pending Approval.';$type='success';
 }catch(DomainException $ex){$message=$ex->getMessage();}catch(mysqli_sql_exception $ex){$message='Could not add this result. It may have changed, be locked, or need the academic database upgrade.';}
}
?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Add Result</title><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="modern-ui.css?v=20261006-modern2"></head><body><div class="main-wrapper"><?php include 'admin_nav.php';?><main class="content"><section class="page-heading"><div><span class="page-kicker">Result Entry</span><h1>Add Result</h1><p>All new records are submitted for Registrar approval before publication.</p></div></section><section class="feature-card"><?php if(!$subjects):?><div class="message error">No active subjects are available. Add subjects in <a href="subject_master.php">Subject Master</a> first.</div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Student ID</label><input name="student_id" required pattern="^SEU/IS/\d{2}/(PS|BS)/\d{3}$" placeholder="SEU/IS/00/PS/000" value="<?=e($_POST['student_id']??'')?>"><div class="form-grid-2"><div><label>Academic Year</label><select name="year" required><option value="">Select Year</option><?php for($i=1;$i<=4;$i++):?><option value="<?=$i?>" <?=($_POST['year']??'')==(string)$i?'selected':''?>>Year <?=$i?></option><?php endfor;?></select></div><div><label>Semester</label><select name="semester" required><option value="">Select Semester</option><option value="1" <?=($_POST['semester']??'')==='1'?'selected':''?>>Semester 1</option><option value="2" <?=($_POST['semester']??'')==='2'?'selected':''?>>Semester 2</option></select></div></div><label>Subject</label><select name="subject_id" required><option value="">Select from Subject Master</option><?php foreach($subjects as $s):?><option value="<?=(int)$s['id']?>" <?=($_POST['subject_id']??'')==(string)$s['id']?'selected':''?>><?=e($s['subject_code'].' · '.$s['subject_name'].' · Y'.$s['year'].' S'.$s['semester'].' · '.$s['section'].' · '.$s['credit'].'cr · '.($s['curriculum_batch']!==''?'Batch '.$s['curriculum_batch']:'Shared').((int)$s['includes_gpa']?' · GPA':' · Non-GPA').(!$s['is_active']?' · Repeat only':''))?></option><?php endforeach;?></select><div class="form-grid-2"><div><label>Entry type</label><select name="entry_kind"><option value="original" <?=($_POST['entry_kind']??'original')==='original'?'selected':''?>>First attempt</option><option value="repeat" <?=($_POST['entry_kind']??'')==='repeat'?'selected':''?>>Repeat attempt</option></select></div><div><label>Examination date (required for repeats)</label><input type="date" name="exam_date" max="<?=date('Y-m-d')?>" value="<?=e($_POST['exam_date']??'')?>"></div></div><div class="field-hint">For repeats use the original subject version. The previous attempt must already be approved and published.</div><label>Marks (0-100)</label><input type="number" name="marks" min="0" max="100" step="0.01" required value="<?=e($_POST['marks']??'')?>"><?php if(false):?><label>Publication Status</label><select name="publish_status"><option value="draft">Draft</option><option value="published">Published</option><option value="withheld">Withheld</option></select><?php endif;?><div class="field-hint">Data Entry submissions remain Draft until approved. Locked semesters cannot be modified.</div><div class="button-row"><a href="admin_dashboard.php" class="btn-link btn-secondary">Back</a><input type="submit" value="Add Result"></div></form><?php if($message):?><div class="message <?=$type?>"><?=e($message)?></div><?php endif;?></section></main><?php include 'footer.php';?></div></body></html>